import { useEffect, useState } from 'react';
import { Link, Route, Switch, useLocation } from 'wouter';
import {
  Activity, ArrowUpRight, BookOpen, Check, ChevronRight, CircleDot,
  Clock3, Flame, Focus, LayoutDashboard, ListTodo, Moon, Pause,
  PenLine, Pencil, Play, Plus, Repeat2, RotateCcw, Save, Search, Settings2,
  Sparkles, StickyNote, Sun, Target, TimerReset, Trash2, TrendingUp, X,
} from 'lucide-react';
import { ErrorBoundary } from '@/components/error-boundary';
import {
  type FocusTimer, type Goal, type Habit, type Note, type Profile, type Store, type Subject,
  type StudyGoal, type Task, loadStore, newId, saveStore, todayKey,
} from '@/lib/storage';

const navItems = [
  { href: '/', label: 'Overview', icon: LayoutDashboard },
  { href: '/tasks', label: 'Tasks', icon: ListTodo },
  { href: '/study', label: 'Study lab', icon: BookOpen },
  { href: '/habits', label: 'Habits', icon: Repeat2 },
  { href: '/goals', label: 'Goals', icon: Target },
  { href: '/notes', label: 'Notes', icon: StickyNote },
];
const colors = ['#c8ef64', '#ff896f', '#89b4ff', '#d8a7ff', '#f3c969'];
const today = todayKey();

const cx = (...classes: Array<string | false | undefined>) => classes.filter(Boolean).join(' ');
const formatDate = (date: Date) => date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
const shortDate = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const initials = (name: string) => name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();
const timeGreeting = (date: Date) => {
  const hour = date.getHours();
  if (hour < 12) return 'Good morning';
  if (hour < 18) return 'Good afternoon';
  return 'Good evening';
};

function Button({ children, variant = 'primary', className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'soft' | 'danger' }) {
  return <button {...props} className={cx(
    'pressable inline-flex items-center justify-center gap-2 rounded-xl px-3.5 py-2 text-sm font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-40',
    variant === 'primary' && 'bg-primary text-primary-foreground hover:brightness-105',
    variant === 'ghost' && 'border border-border bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground',
    variant === 'soft' && 'bg-secondary text-secondary-foreground hover:bg-primary/15 hover:text-primary',
    variant === 'danger' && 'bg-destructive/10 text-destructive hover:bg-destructive/20',
    className,
  )} />;
}
function IconButton({ label, children, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { label: string }) {
  return <button {...props} aria-label={label} data-testid={`button-${label.toLowerCase().replaceAll(' ', '-')}`} className={cx('pressable inline-flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground hover:bg-secondary hover:text-foreground', props.className)}>{children}</button>;
}
function Card({ children, className = '', ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div {...props} className={cx('glass rounded-2xl', className)}>{children}</div>;
}
function Progress({ value, color = 'bg-primary', className = '' }: { value: number; color?: string; className?: string }) {
  return <div className={cx('h-2 overflow-hidden rounded-full bg-secondary', className)}><div className={cx('bar-fill h-full rounded-full', color)} style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>;
}
function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) {
  return <div className="mb-4 flex items-end justify-between gap-3"><div>{eyebrow && <p className="mb-1 font-mono text-[10px] uppercase tracking-[.18em] text-primary">{eyebrow}</p>}<h2 className="text-lg font-semibold tracking-tight">{title}</h2></div>{action}</div>;
}
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: React.ReactNode }) {
  return <div className="rounded-xl border border-dashed border-border bg-secondary/30 px-5 py-8 text-center"><CircleDot className="mx-auto mb-3 h-5 w-5 text-muted-foreground" /><p className="text-sm font-medium">{title}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) {
  return <div className="fixed inset-0 z-40 flex items-end justify-center bg-background/75 p-3 backdrop-blur-sm sm:items-center" role="dialog" aria-modal="true"><div className="glass max-h-[92dvh] w-full max-w-lg overflow-auto rounded-2xl p-5 shadow-2xl"><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-semibold">{title}</h2><IconButton label="close dialog" onClick={onClose}><X className="h-4 w-4" /></IconButton></div>{children}</div></div>;
}
function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">{label}{children}</label>;
}
const inputClass = 'w-full rounded-xl border border-input bg-secondary/60 px-3 py-2.5 text-sm text-foreground placeholder:text-muted-foreground/60';
function Layout({ store, children }: { store: Store; children: React.ReactNode }) {
  const [location, setLocation] = useLocation();
  const [mobileNav, setMobileNav] = useState(false);
  const [now, setNow] = useState(new Date());
  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 1000); return () => window.clearInterval(timer); }, []);
  return <div className="app-noise min-h-[100dvh]">
    <aside className={cx('fixed inset-y-0 left-0 z-30 flex w-[248px] flex-col border-r border-border/70 bg-card/80 p-5 backdrop-blur-xl transition-transform lg:translate-x-0', mobileNav ? 'translate-x-0' : '-translate-x-full')}>
      <div className="mb-10 flex items-center justify-between"><Link href="/" className="flex items-center gap-3" data-testid="link-logo"><span className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-primary-foreground"><Sparkles className="h-4 w-4" /></span><span><strong className="block text-sm tracking-tight">command centre</strong><span className="font-mono text-[9px] uppercase tracking-[.15em] text-muted-foreground">personal / v1</span></span></Link><IconButton label="close navigation" className="lg:hidden" onClick={() => setMobileNav(false)}><X className="h-4 w-4" /></IconButton></div>
      <p className="mb-3 px-3 font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Your space</p>
      <nav className="grid gap-1">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileNav(false)} data-testid={`link-nav-${label.toLowerCase().replace(' ', '-')}`} className={cx('group flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition-colors', location === href ? 'bg-primary/12 font-semibold text-primary' : 'text-muted-foreground hover:bg-secondary hover:text-foreground')}><Icon className="h-[17px] w-[17px]" /><span>{label}</span>{location === href && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-primary" />}</Link>)}</nav>
      <div className="mt-auto grid gap-1"><Link href="/settings" onClick={() => setMobileNav(false)} data-testid="link-nav-settings" className={cx('flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition-colors', location === '/settings' ? 'bg-primary/12 font-semibold text-primary' : 'text-muted-foreground hover:bg-secondary hover:text-foreground')}><Settings2 className="h-[17px] w-[17px]" />Settings</Link><div className="mt-4 rounded-xl border border-border bg-secondary/50 p-3"><div className="mb-2 flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Today</span><Activity className="h-3.5 w-3.5 text-primary" /></div><p className="font-mono text-lg">{now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p><p className="mt-1 text-xs text-muted-foreground">{formatDate(now)}</p></div></div>
    </aside>
    {mobileNav && <button aria-label="close navigation overlay" className="fixed inset-0 z-20 bg-background/60 lg:hidden" onClick={() => setMobileNav(false)} />}
    <main className="min-h-[100dvh] lg:pl-[248px]"><header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-border/60 bg-background/72 px-4 backdrop-blur-xl sm:px-7 lg:px-10"><div className="flex items-center gap-3"><IconButton label="open navigation" className="lg:hidden" onClick={() => setMobileNav(true)}><ListTodo className="h-5 w-5" /></IconButton><div className="hidden font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground sm:block">Personal operating system <span className="mx-2 text-primary">/</span> {location === '/' ? 'overview' : location.slice(1)}</div></div><div className="flex items-center gap-3"><Link href="/settings" className="flex items-center gap-2 rounded-full border border-border bg-secondary/70 py-1 pl-1 pr-3 text-xs font-medium hover:border-primary/40" data-testid="link-profile"><span className="grid h-7 w-7 place-items-center rounded-full bg-accent/15 font-mono text-[10px] text-accent">{initials(store.profile.name)}</span><span className="hidden sm:block">{store.profile.name}</span></Link></div></header><div className="mx-auto max-w-[1440px] p-4 sm:p-7 lg:p-10">{children}</div></main>
  </div>;
}

function Dashboard({ store, update }: PageProps) {
  const [, setLocation] = useLocation();
  const [now, setNow] = useState(new Date());
  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 1000); return () => window.clearInterval(timer); }, []);
  const todayTasks = store.tasks.filter((task) => task.dueDate === today);
  const done = todayTasks.filter((task) => task.status === 'done').length;
  const habitDone = store.habits.filter((habit) => habit.completedDates.includes(today)).length;
  const activeGoal = store.goals.find((goal) => goal.status === 'active');
  const focus = store.focusTimer;
  const nextTask = todayTasks.find((task) => task.status !== 'done');
  const upcomingTasks = store.tasks.filter((task) => task.dueDate > today).sort((a, b) => `${a.dueDate}${a.dueTime}`.localeCompare(`${b.dueDate}${b.dueTime}`)).slice(0, 3);
  const toggleTask = (id: string) => update({ tasks: store.tasks.map((task) => task.id === id ? { ...task, status: task.status === 'done' ? 'todo' : 'done' } : task) });
  const toggleHabit = (id: string) => update({ habits: store.habits.map((habit) => habit.id === id ? { ...habit, completedDates: habit.completedDates.includes(today) ? habit.completedDates.filter((date) => date !== today) : [...habit.completedDates, today] } : habit) });
  return <div className="space-y-7">
    <div className="rise flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mb-2 font-mono text-[10px] uppercase tracking-[.2em] text-primary">{now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}</p><h1 className="text-3xl font-semibold tracking-[-.04em] sm:text-4xl">{timeGreeting(now)}, {store.profile.name.split(' ')[0]}<span className="text-primary">.</span></h1><p className="mt-2 max-w-xl text-sm text-muted-foreground">{store.profile.focus}</p></div><div className="flex items-center gap-2"><Button variant="soft" onClick={() => setLocation('/notes')} data-testid="button-quick-note"><PenLine className="h-4 w-4" />Quick note</Button><Button onClick={() => setLocation('/tasks')} data-testid="button-quick-task"><Plus className="h-4 w-4" />Add task</Button></div></div>
    <div className="grid gap-4 lg:grid-cols-[1.45fr_.75fr_.75fr]">
      <Card className="rise-1 relative overflow-hidden p-5 sm:p-6"><div className="absolute -right-14 -top-20 h-52 w-52 rounded-full bg-primary/10 blur-3xl" /><div className="relative flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Daily momentum</p><p className="mt-4 text-4xl font-semibold tracking-[-.06em]">{Math.round((done / Math.max(todayTasks.length, 1)) * 100)}<span className="text-xl text-muted-foreground">%</span></p><p className="mt-1 text-sm text-muted-foreground">{done} of {todayTasks.length} tasks in motion</p></div><div className="grid h-14 w-14 place-items-center rounded-full border-4 border-primary/20 border-t-primary text-xs font-mono text-primary">{done}/{todayTasks.length}</div></div><Progress value={(done / Math.max(todayTasks.length, 1)) * 100} className="mt-7" /><div className="mt-5 flex items-center justify-between text-xs text-muted-foreground"><span>Keep the line moving</span><span className="font-mono text-primary">{now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span></div></Card>
      <Card className="rise-2 p-5"><div className="flex items-center justify-between"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Focus timer</p><Focus className="h-4 w-4 text-accent" /></div><p className="mt-5 font-mono text-3xl tracking-tight">{String(focus.minutesLeft).padStart(2, '0')}:00</p><p className="mt-1 text-xs text-muted-foreground">{focus.mode === 'focus' ? 'A pocket for deep work' : 'A small reset'}</p><Button variant="soft" className="mt-5 w-full" onClick={() => setLocation('/study')} data-testid="button-open-focus">{focus.isRunning ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}{focus.isRunning ? 'Running now' : 'Open focus mode'}</Button></Card>
      <Card className="rise-3 p-5"><div className="flex items-center justify-between"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Habit rhythm</p><Flame className="h-4 w-4 text-primary" /></div><p className="mt-5 font-mono text-3xl tracking-tight">{habitDone}<span className="text-base text-muted-foreground">/{store.habits.length}</span></p><p className="mt-1 text-xs text-muted-foreground">rituals checked today</p><Progress value={(habitDone / Math.max(store.habits.length, 1)) * 100} color="bg-accent" className="mt-5" /></Card>
    </div>
    <div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="The next right thing" title="Today's tasks" action={<Link href="/tasks" className="inline-flex items-center gap-1 text-xs font-semibold text-primary" data-testid="link-view-tasks">View all <ArrowUpRight className="h-3.5 w-3.5" /></Link>} />{todayTasks.length === 0 ? <EmptyState title="A clear runway" detail="Nothing is due today. Add something worth moving." /> : <div className="grid gap-2">{todayTasks.map((task) => <TaskRow key={task.id} task={task} onToggle={() => toggleTask(task.id)} />)}</div>}</Card>
      <Card className="p-5 sm:p-6"><SectionHeading eyebrow="Long game" title="Active goal" action={<Link href="/goals" className="text-xs font-semibold text-primary" data-testid="link-view-goals">See goals</Link>} />{activeGoal ? <div><div className="mb-5 flex items-start justify-between gap-3"><div><h3 className="font-semibold">{activeGoal.title}</h3><p className="mt-1 text-xs leading-relaxed text-muted-foreground">{activeGoal.description}</p></div><span className="rounded-md bg-primary/10 px-2 py-1 font-mono text-[10px] text-primary">{activeGoal.progress}%</span></div><Progress value={activeGoal.progress} /><div className="mt-3 flex justify-between text-xs text-muted-foreground"><span>{activeGoal.category}</span><span>Due {shortDate(activeGoal.deadline)}</span></div></div> : <EmptyState title="Choose a north star" detail="Create a goal to give the week a little gravity." />}</Card></div>
    <Card className="p-5 sm:p-6"><SectionHeading eyebrow="On the horizon" title="Upcoming" action={<Link href="/tasks" className="text-xs font-semibold text-primary" data-testid="link-view-upcoming">Manage tasks</Link>} />{upcomingTasks.length ? <div className="grid gap-2 sm:grid-cols-3">{upcomingTasks.map((task) => <div key={task.id} className="rounded-xl border border-border bg-secondary/30 p-3"><p className="truncate text-sm font-medium">{task.title}</p><p className="mt-2 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{shortDate(task.dueDate)}{task.dueTime ? ` · ${task.dueTime}` : ''}</p></div>)}</div> : <EmptyState title="Nothing queued beyond today" detail="Future tasks will appear here when you give them a due date." action={<Button variant="soft" onClick={() => setLocation('/tasks')}>Plan ahead</Button>} />}</Card>
    <div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Small promises" title="Habits" action={<Link href="/habits" className="text-xs font-semibold text-primary" data-testid="link-view-habits">Manage</Link>} />{store.habits.length === 0 ? <EmptyState title="No rituals yet" detail="Start with one action you want to return to." /> : <div className="grid gap-2">{store.habits.slice(0, 4).map((habit) => <button key={habit.id} data-testid={`button-habit-${habit.id}`} onClick={() => toggleHabit(habit.id)} className={cx('pressable flex items-center gap-3 rounded-xl border px-3 py-3 text-left', habit.completedDates.includes(today) ? 'border-primary/30 bg-primary/8' : 'border-border bg-secondary/30')}><span className="grid h-8 w-8 place-items-center rounded-lg" style={{ backgroundColor: `${habit.color}20`, color: habit.color }}><Repeat2 className="h-4 w-4" /></span><span className="min-w-0 flex-1 truncate text-sm">{habit.name}</span><span className={cx('grid h-5 w-5 place-items-center rounded-full border', habit.completedDates.includes(today) ? 'border-primary bg-primary text-primary-foreground' : 'border-border text-transparent')}><Check className="h-3 w-3" /></span></button>)}</div>}</Card>
      <Card className="relative overflow-hidden p-5 sm:p-6"><div className="absolute right-0 top-0 h-full w-1/3 bg-gradient-to-l from-accent/8 to-transparent" /><SectionHeading eyebrow="A note to self" title="Keep it useful" /><blockquote className="relative max-w-2xl text-xl font-medium leading-relaxed tracking-tight sm:text-2xl">“The work gets lighter when the next step is visible.”</blockquote><p className="relative mt-5 font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Morning brief / {now.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</p>{nextTask && <button onClick={() => toggleTask(nextTask.id)} className="relative mt-6 flex items-center gap-2 text-xs font-semibold text-primary" data-testid="button-next-task">Start with “{nextTask.title}” <ChevronRight className="h-3.5 w-3.5" /></button>}</Card></div>
  </div>;
}

function TaskRow({ task, onToggle, onEdit, onDelete }: { task: Task; onToggle: () => void; onEdit?: () => void; onDelete?: () => void }) {
  return <div className="group flex items-center gap-3 rounded-xl border border-border bg-secondary/30 px-3 py-3"><button aria-label={`complete ${task.title}`} data-testid={`button-complete-${task.id}`} onClick={onToggle} className={cx('check-pop grid h-5 w-5 shrink-0 place-items-center rounded-full border transition-colors', task.status === 'done' ? 'border-primary bg-primary text-primary-foreground' : 'border-muted-foreground/50 text-transparent hover:border-primary')}><Check className="h-3 w-3" /></button><div className="min-w-0 flex-1"><p className={cx('truncate text-sm font-medium', task.status === 'done' && 'text-muted-foreground line-through')}>{task.title}</p><div className="mt-1 flex items-center gap-2 text-[10px] text-muted-foreground"><Clock3 className="h-3 w-3" />{task.dueTime || 'Anytime'}<span className="h-1 w-1 rounded-full bg-border" /><span className={cx(task.priority === 'high' ? 'text-accent' : task.priority === 'medium' ? 'text-primary' : '')}>{task.priority}</span></div></div>{(onEdit || onDelete) && <div className="flex opacity-100 sm:opacity-0 sm:transition-opacity sm:group-hover:opacity-100">{onEdit && <IconButton label={`edit ${task.title}`} onClick={onEdit}><Pencil className="h-3.5 w-3.5" /></IconButton>}{onDelete && <IconButton label={`delete ${task.title}`} onClick={onDelete}><Trash2 className="h-3.5 w-3.5" /></IconButton>}</div>}</div>;
}

type PageProps = { store: Store; update: (patch: Partial<Store>) => void };
function TasksPage({ store, update }: PageProps) {
  const [filter, setFilter] = useState<'all' | 'today' | 'open' | 'done'>('all');
  const [modal, setModal] = useState<'new' | Task | null>(null);
  const visible = store.tasks.filter((task) => filter === 'all' || (filter === 'today' && task.dueDate === today) || (filter === 'open' && task.status === 'todo') || (filter === 'done' && task.status === 'done'));
  const saveTask = (value: Omit<Task, 'id' | 'createdAt'>, editing?: Task) => update({ tasks: editing ? store.tasks.map((task) => task.id === editing.id ? { ...task, ...value } : task) : [{ ...value, id: newId('task'), createdAt: new Date().toISOString() }, ...store.tasks] });
  const toggle = (id: string) => update({ tasks: store.tasks.map((task) => task.id === id ? { ...task, status: task.status === 'done' ? 'todo' : 'done' } : task) });
  return <div className="space-y-7"><PageIntro eyebrow="Execution" title="Tasks" detail="Keep the list honest. Fewer open loops, more finished work." action={<Button onClick={() => setModal('new')} data-testid="button-add-task"><Plus className="h-4 w-4" />New task</Button>} /><Card className="p-3 sm:p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div className="flex flex-wrap gap-1">{(['all', 'today', 'open', 'done'] as const).map((key) => <button key={key} data-testid={`button-filter-${key}`} onClick={() => setFilter(key)} className={cx('rounded-lg px-3 py-1.5 text-xs font-semibold capitalize', filter === key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-secondary')}>{key}</button>)}</div><p className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{visible.length} visible / {store.tasks.length} total</p></div></Card><Card className="p-4 sm:p-6"><div className="grid gap-2">{visible.length ? visible.map((task) => <TaskRow key={task.id} task={task} onToggle={() => toggle(task.id)} onEdit={() => setModal(task)} onDelete={() => update({ tasks: store.tasks.filter((item) => item.id !== task.id) })} />) : <EmptyState title="No tasks in this view" detail="The empty space is useful. Or add the next small move." action={<Button onClick={() => setModal('new')}><Plus className="h-4 w-4" />Add a task</Button>} />}</div></Card>{modal && <TaskModal task={modal === 'new' ? undefined : modal} onClose={() => setModal(null)} onSave={(value) => { saveTask(value, modal === 'new' ? undefined : modal); setModal(null); }} />}</div>;
}
function TaskModal({ task, onClose, onSave }: { task?: Task; onClose: () => void; onSave: (value: Omit<Task, 'id' | 'createdAt'>) => void }) {
  const [value, setValue] = useState<Omit<Task, 'id' | 'createdAt'>>(task ? { title: task.title, description: task.description, priority: task.priority, status: task.status, dueDate: task.dueDate, dueTime: task.dueTime } : { title: '', description: '', priority: 'medium', status: 'todo', dueDate: today, dueTime: '' });
  const set = (key: keyof typeof value, next: string) => setValue((old) => ({ ...old, [key]: next }));
  return <Modal title={task ? 'Edit task' : 'New task'} onClose={onClose}><form className="grid gap-4" onSubmit={(event) => { event.preventDefault(); if (value.title.trim()) onSave(value); }}><Field label="Task title"><input autoFocus required className={inputClass} value={value.title} onChange={(e) => set('title', e.target.value)} data-testid="input-task-title" placeholder="What needs your attention?" /></Field><Field label="Context"><textarea className={cx(inputClass, 'min-h-20 resize-y')} value={value.description} onChange={(e) => set('description', e.target.value)} data-testid="input-task-description" placeholder="A little context helps future you." /></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="Priority"><select className={inputClass} value={value.priority} onChange={(e) => set('priority', e.target.value)} data-testid="select-task-priority"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></Field><Field label="Due date"><input type="date" className={inputClass} value={value.dueDate} onChange={(e) => set('dueDate', e.target.value)} data-testid="input-task-date" /></Field><Field label="Time"><input type="time" className={inputClass} value={value.dueTime} onChange={(e) => set('dueTime', e.target.value)} data-testid="input-task-time" /></Field></div><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" data-testid="button-save-task"><Save className="h-4 w-4" />Save task</Button></div></form></Modal>;
}
function PageIntro({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: React.ReactNode }) { return <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 font-mono text-[10px] uppercase tracking-[.2em] text-primary">{eyebrow}</p><h1 className="text-3xl font-semibold tracking-[-.04em]">{title}</h1><p className="mt-2 max-w-xl text-sm text-muted-foreground">{detail}</p></div>{action}</div>; }

function StudyPage({ store, update }: PageProps) {
  const [modal, setModal] = useState<'subject' | 'session' | 'goal' | null>(null);
  const [timer, setTimer] = useState<FocusTimer>(store.focusTimer);
  useEffect(() => { setTimer(store.focusTimer); }, [store.focusTimer]);
  useEffect(() => {
    if (!timer.isRunning) return;
    const id = window.setInterval(() => setTimer((old) => {
      const next = old.minutesLeft <= 1 / 60
        ? { ...old, minutesLeft: 0, isRunning: false }
        : { ...old, minutesLeft: old.minutesLeft - 1 / 60 };
      update({ focusTimer: next });
      return next;
    }), 1000);
    return () => window.clearInterval(id);
  }, [timer.isRunning]);
  const goal = store.studyGoals[0];
  const saveSubject = (name: string, color: string) => update({ subjects: [...store.subjects, { id: newId('subject'), name, color, totalMinutes: 0, topicsCompleted: 0, topicsTotal: 10 }] });
  const saveSession = (subjectId: string, minutes: number, note: string) => update({ studySessions: [{ id: newId('session'), subjectId, minutes, date: today, note }, ...store.studySessions], subjects: store.subjects.map((subject) => subject.id === subjectId ? { ...subject, totalMinutes: subject.totalMinutes + minutes } : subject), studyGoals: store.studyGoals.map((item, index) => index === 0 ? { ...item, completedMinutes: item.completedMinutes + minutes } : item) });
  const saveGoal = (title: string, targetMinutes: number) => update({ studyGoals: [{ id: newId('study-goal'), title, targetMinutes, completedMinutes: 0 }, ...store.studyGoals] });
  return <div className="space-y-7"><PageIntro eyebrow="Learning loop" title="Study lab" detail="Give curiosity a place to land. Track time, not guilt." action={<div className="flex flex-wrap gap-2"><Button variant="soft" onClick={() => setModal('subject')} data-testid="button-add-subject"><Plus className="h-4 w-4" />Subject</Button><Button variant="soft" onClick={() => setModal('goal')} data-testid="button-add-study-goal"><Target className="h-4 w-4" />Study goal</Button><Button onClick={() => setModal('session')} data-testid="button-log-session"><Clock3 className="h-4 w-4" />Log session</Button></div>} /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><Card className="relative overflow-hidden p-6"><div className="absolute -right-10 -top-10 h-40 w-40 rounded-full bg-accent/10 blur-3xl" /><div className="relative"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Focus room</p><div className="mt-8 text-center"><p className="font-mono text-6xl tracking-[-.08em] text-foreground">{String(Math.floor(timer.minutesLeft)).padStart(2, '0')}<span className="text-primary">:</span>{String(Math.floor((timer.minutesLeft % 1) * 60)).padStart(2, '0')}</p><p className="mt-3 text-sm text-muted-foreground">{timer.mode === 'focus' ? 'One clean block. That is enough.' : 'Reset your attention.'}</p></div><div className="mt-8 flex justify-center gap-2"><Button onClick={() => setTimer({ ...timer, isRunning: !timer.isRunning })} data-testid="button-toggle-timer">{timer.isRunning ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}{timer.isRunning ? 'Pause' : 'Start focus'}</Button><IconButton label="reset timer" onClick={() => setTimer({ mode: 'focus', minutesLeft: 25, isRunning: false })}><TimerReset className="h-4 w-4" /></IconButton></div></div></Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="This week" title={goal?.title || 'Study goal'} action={<div className="flex items-center gap-2">{goal && <span className="font-mono text-xs text-primary">{goal.completedMinutes}/{goal.targetMinutes} min</span>}<IconButton label="add study goal" onClick={() => setModal('goal')}><Plus className="h-4 w-4" /></IconButton></div>} />{goal ? <><Progress value={(goal.completedMinutes / goal.targetMinutes) * 100} color="bg-accent" /><div className="mt-6 grid grid-cols-3 gap-2 text-center"><div className="rounded-xl bg-secondary/50 p-3"><p className="font-mono text-lg">{store.studySessions.filter((item) => item.date === today).reduce((sum, item) => sum + item.minutes, 0)}</p><p className="mt-1 text-[10px] text-muted-foreground">minutes today</p></div><div className="rounded-xl bg-secondary/50 p-3"><p className="font-mono text-lg">{store.subjects.length}</p><p className="mt-1 text-[10px] text-muted-foreground">subjects</p></div><div className="rounded-xl bg-secondary/50 p-3"><p className="font-mono text-lg">{store.subjects.reduce((sum, item) => sum + item.topicsCompleted, 0)}</p><p className="mt-1 text-[10px] text-muted-foreground">topics done</p></div></div></> : <EmptyState title="Set a study goal" detail="Give the next block a little shape." action={<Button onClick={() => setModal('goal')}>Add a goal</Button>} />}</Card></div><div className="grid gap-5 lg:grid-cols-[1fr_.85fr]"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="The syllabus" title="Subjects" />{store.subjects.length ? <div className="grid gap-3">{store.subjects.map((subject) => <SubjectRow key={subject.id} subject={subject} onAdvance={() => update({ subjects: store.subjects.map((item) => item.id === subject.id ? { ...item, topicsCompleted: Math.min(item.topicsTotal, item.topicsCompleted + 1) } : item) })} />)}</div> : <EmptyState title="No subjects yet" detail="Add the thing you are curious about." action={<Button onClick={() => setModal('subject')}>Add subject</Button>} />}</Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Recent reps" title="Study sessions" />{store.studySessions.length ? <div className="grid gap-2">{store.studySessions.slice(0, 5).map((session) => <div key={session.id} className="flex items-center gap-3 rounded-xl border border-border bg-secondary/30 p-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-accent/12 text-accent"><Clock3 className="h-4 w-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{store.subjects.find((s) => s.id === session.subjectId)?.name || 'Unknown subject'}</p><p className="text-xs text-muted-foreground">{session.note || 'Focused study'} · {shortDate(session.date)}</p></div><span className="font-mono text-xs text-primary">{session.minutes}m</span></div>)}</div> : <EmptyState title="No sessions logged" detail="Your first focused block starts the record." />}</Card></div>{modal === 'subject' && <SubjectModal onClose={() => setModal(null)} onSave={(name, color) => { saveSubject(name, color); setModal(null); }} />}{modal === 'session' && <SessionModal subjects={store.subjects} onClose={() => setModal(null)} onSave={(subjectId, minutes, note) => { saveSession(subjectId, minutes, note); setModal(null); }} />}{modal === 'goal' && <StudyGoalModal onClose={() => setModal(null)} onSave={(title, targetMinutes) => { saveGoal(title, targetMinutes); setModal(null); }} />}</div>;
}
function SubjectRow({ subject, onAdvance }: { subject: Subject; onAdvance: () => void }) { return <div className="rounded-xl border border-border bg-secondary/30 p-4"><div className="flex items-center justify-between gap-4"><div className="flex items-center gap-3"><span className="h-3 w-3 rounded-full" style={{ backgroundColor: subject.color }} /><p className="text-sm font-semibold">{subject.name}</p></div><span className="font-mono text-xs text-muted-foreground">{subject.totalMinutes}m</span></div><div className="mt-4 flex items-center gap-3"><Progress value={(subject.topicsCompleted / Math.max(subject.topicsTotal, 1)) * 100} color="" className="flex-1" /><span className="text-[10px] text-muted-foreground">{subject.topicsCompleted}/{subject.topicsTotal} topics</span><button onClick={onAdvance} disabled={subject.topicsCompleted >= subject.topicsTotal} data-testid={`button-topic-${subject.id}`} className="rounded-lg bg-primary/12 px-2 py-1 text-[10px] font-semibold text-primary disabled:opacity-40">+ topic</button></div></div>; }
function SubjectModal({ onClose, onSave }: { onClose: () => void; onSave: (name: string, color: string) => void }) { const [name, setName] = useState(''); const [color, setColor] = useState(colors[0]); return <Modal title="New subject" onClose={onClose}><form className="grid gap-4" onSubmit={(e) => { e.preventDefault(); if (name.trim()) onSave(name, color); }}><Field label="Subject name"><input autoFocus required className={inputClass} value={name} onChange={(e) => setName(e.target.value)} data-testid="input-subject-name" placeholder="e.g. Typography" /></Field><Field label="Marker color"><div className="flex gap-2">{colors.map((item) => <button type="button" aria-label={`choose ${item} color`} key={item} onClick={() => setColor(item)} className={cx('h-8 w-8 rounded-full border-2', color === item ? 'border-foreground' : 'border-transparent')} style={{ backgroundColor: item }} />)}</div></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Add subject</Button></div></form></Modal>; }
function SessionModal({ subjects, onClose, onSave }: { subjects: Subject[]; onClose: () => void; onSave: (subjectId: string, minutes: number, note: string) => void }) { const [subjectId, setSubjectId] = useState(subjects[0]?.id || ''); const [minutes, setMinutes] = useState('25'); const [note, setNote] = useState(''); return <Modal title="Log study session" onClose={onClose}><form className="grid gap-4" onSubmit={(e) => { e.preventDefault(); if (subjectId && Number(minutes) > 0) onSave(subjectId, Number(minutes), note); }}><Field label="Subject"><select required className={inputClass} value={subjectId} onChange={(e) => setSubjectId(e.target.value)} data-testid="select-session-subject">{subjects.map((subject) => <option key={subject.id} value={subject.id}>{subject.name}</option>)}</select></Field><Field label="Minutes"><input required type="number" min="1" className={inputClass} value={minutes} onChange={(e) => setMinutes(e.target.value)} data-testid="input-session-minutes" /></Field><Field label="What moved?"><input className={inputClass} value={note} onChange={(e) => setNote(e.target.value)} data-testid="input-session-note" placeholder="A phrase is enough." /></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Log session</Button></div></form></Modal>; }
function StudyGoalModal({ onClose, onSave }: { onClose: () => void; onSave: (title: string, targetMinutes: number) => void }) { const [title, setTitle] = useState(''); const [target, setTarget] = useState('300'); return <Modal title="New study goal" onClose={onClose}><form className="grid gap-4" onSubmit={(e) => { e.preventDefault(); if (title.trim() && Number(target) > 0) onSave(title, Number(target)); }}><Field label="Goal"><input autoFocus required className={inputClass} value={title} onChange={(e) => setTitle(e.target.value)} data-testid="input-study-goal-title" placeholder="e.g. Read three chapters" /></Field><Field label="Target minutes"><input required type="number" min="1" className={inputClass} value={target} onChange={(e) => setTarget(e.target.value)} data-testid="input-study-goal-minutes" /></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Add study goal</Button></div></form></Modal>; }

function HabitsPage({ store, update }: PageProps) {
  const [modal, setModal] = useState(false);
  const toggle = (id: string) => update({ habits: store.habits.map((habit) => habit.id === id ? { ...habit, completedDates: habit.completedDates.includes(today) ? habit.completedDates.filter((date) => date !== today) : [...habit.completedDates, today] } : habit) });
  const add = (name: string, color: string, frequency: string) => update({ habits: [...store.habits, { id: newId('habit'), name, icon: 'circle', color, frequency, completedDates: [], createdAt: new Date().toISOString() }] });
  return <div className="space-y-7"><PageIntro eyebrow="Daily rhythm" title="Habits" detail="Tiny repetitions become the atmosphere of a life." action={<Button onClick={() => setModal(true)} data-testid="button-add-habit"><Plus className="h-4 w-4" />New habit</Button>} /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Today" value={`${store.habits.filter((h) => h.completedDates.includes(today)).length}/${store.habits.length}`} detail="rituals complete" icon={<Check className="h-4 w-4" />} /><StatCard label="Current streak" value={`${Math.max(...store.habits.map((h) => streak(h.completedDates)), 0)}`} detail="days at best" icon={<Flame className="h-4 w-4" />} accent /><StatCard label="Consistency" value={`${Math.round(store.habits.reduce((sum, h) => sum + Math.min(streak(h.completedDates), 7), 0) / Math.max(store.habits.length * 7, 1) * 100)}%`} detail="last 7 days" icon={<TrendingUp className="h-4 w-4" />} /></div><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Your rituals" title="Show up for yourself" />{store.habits.length ? <div className="grid gap-3 md:grid-cols-2">{store.habits.map((habit) => { const checked = habit.completedDates.includes(today); return <div key={habit.id} className={cx('rounded-2xl border p-4 transition-colors', checked ? 'border-primary/35 bg-primary/7' : 'border-border bg-secondary/25')}><div className="flex items-start gap-3"><button aria-label={`complete habit ${habit.name}`} data-testid={`button-complete-habit-${habit.id}`} onClick={() => toggle(habit.id)} className={cx('grid h-10 w-10 shrink-0 place-items-center rounded-xl border', checked ? 'border-primary bg-primary text-primary-foreground' : 'border-border text-muted-foreground')}><Check className="h-4 w-4" /></button><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><h3 className="font-semibold">{habit.name}</h3><p className="mt-1 text-xs text-muted-foreground">{habit.frequency} · started {shortDate(habit.createdAt.slice(0, 10))}</p></div><span className="rounded-md px-2 py-1 font-mono text-[10px]" style={{ backgroundColor: `${habit.color}18`, color: habit.color }}>{streak(habit.completedDates)} day streak</span></div><div className="mt-4 flex gap-1">{Array.from({ length: 7 }).map((_, index) => { const date = new Date(); date.setDate(date.getDate() - (6 - index)); const key = date.toISOString().slice(0, 10); return <span key={key} title={key} className={cx('h-1.5 flex-1 rounded-full', habit.completedDates.includes(key) ? 'bg-primary' : 'bg-secondary')} />; })}</div></div></div></div>; })}</div> : <EmptyState title="Your ritual shelf is empty" detail="Add one thing that makes tomorrow easier." action={<Button onClick={() => setModal(true)}>Add a habit</Button>} />}</Card>{modal && <HabitModal onClose={() => setModal(false)} onSave={(name, color, frequency) => { add(name, color, frequency); setModal(false); }} />}</div>;
}
function streak(dates: string[]) { let count = 0; const cursor = new Date(); while (dates.includes(cursor.toISOString().slice(0, 10))) { count++; cursor.setDate(cursor.getDate() - 1); } return count; }
function StatCard({ label, value, detail, icon, accent }: { label: string; value: string; detail: string; icon: React.ReactNode; accent?: boolean }) { return <Card className="p-4"><div className={cx('mb-4 grid h-8 w-8 place-items-center rounded-lg', accent ? 'bg-accent/15 text-accent' : 'bg-primary/12 text-primary')}>{icon}</div><p className="font-mono text-2xl">{value}</p><p className="mt-1 text-xs text-muted-foreground">{label} · {detail}</p></Card>; }
function HabitModal({ onClose, onSave }: { onClose: () => void; onSave: (name: string, color: string, frequency: string) => void }) { const [name, setName] = useState(''); const [color, setColor] = useState(colors[1]); const [frequency, setFrequency] = useState('Daily'); return <Modal title="New habit" onClose={onClose}><form className="grid gap-4" onSubmit={(e) => { e.preventDefault(); if (name.trim()) onSave(name, color, frequency); }}><Field label="Habit"><input autoFocus required className={inputClass} value={name} onChange={(e) => setName(e.target.value)} data-testid="input-habit-name" placeholder="e.g. Stretch for five minutes" /></Field><Field label="Frequency"><select className={inputClass} value={frequency} onChange={(e) => setFrequency(e.target.value)} data-testid="select-habit-frequency"><option>Daily</option><option>Weekdays</option><option>Weekly</option></select></Field><Field label="Color"><div className="flex gap-2">{colors.map((item) => <button type="button" aria-label={`choose ${item} color`} key={item} onClick={() => setColor(item)} className={cx('h-8 w-8 rounded-full border-2', color === item ? 'border-foreground' : 'border-transparent')} style={{ backgroundColor: item }} />)}</div></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Add habit</Button></div></form></Modal>; }

function GoalsPage({ store, update }: PageProps) {
  const [filter, setFilter] = useState<'active' | 'completed'>('active'); const [modal, setModal] = useState(false);
  const visible = store.goals.filter((goal) => goal.status === filter);
  const add = (value: Omit<Goal, 'id' | 'status' | 'progress'>) => update({ goals: [{ ...value, id: newId('goal'), status: 'active', progress: 0 }, ...store.goals] });
  const updateGoal = (id: string, patch: Partial<Goal>) => update({ goals: store.goals.map((goal) => goal.id === id ? { ...goal, ...patch, status: patch.progress === 100 ? 'completed' : goal.status } : goal) });
  return <div className="space-y-7"><PageIntro eyebrow="North stars" title="Goals" detail="The horizon is more useful when you can see your progress against it." action={<Button onClick={() => setModal(true)} data-testid="button-add-goal"><Plus className="h-4 w-4" />New goal</Button>} /><div className="flex gap-1 rounded-xl border border-border bg-secondary/35 p-1 w-fit">{(['active', 'completed'] as const).map((key) => <button key={key} onClick={() => setFilter(key)} data-testid={`button-goals-${key}`} className={cx('rounded-lg px-4 py-2 text-xs font-semibold capitalize', filter === key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground')}>{key}</button>)}</div><div className="grid gap-4 lg:grid-cols-2">{visible.length ? visible.map((goal) => <Card key={goal.id} className="p-5"><div className="flex items-start justify-between gap-4"><div><div className="flex items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-wider text-accent">{goal.category}</span><span className="rounded-md bg-secondary px-2 py-1 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{goal.term}-term</span></div><h2 className="mt-2 text-lg font-semibold">{goal.title}</h2><p className="mt-1 text-sm leading-relaxed text-muted-foreground">{goal.description}</p></div><span className="font-mono text-sm text-primary">{goal.progress}%</span></div><div className="mt-6"><Progress value={goal.progress} /><div className="mt-3 flex items-center justify-between text-xs text-muted-foreground"><span>Due {shortDate(goal.deadline)}</span>{goal.status === 'active' ? <div className="flex items-center gap-1"><button onClick={() => updateGoal(goal.id, { progress: Math.max(0, goal.progress - 10) })} className="rounded-md bg-secondary px-2 py-1" data-testid={`button-decrease-goal-${goal.id}`}>−</button><button onClick={() => updateGoal(goal.id, { progress: Math.min(100, goal.progress + 10) })} className="rounded-md bg-secondary px-2 py-1" data-testid={`button-increase-goal-${goal.id}`}>+10</button></div> : <span className="text-primary">Completed</span>}</div></div></Card>) : <div className="lg:col-span-2"><EmptyState title={filter === 'active' ? 'No active goals' : 'No completed goals'} detail={filter === 'active' ? 'Give the next season a clear shape.' : 'Finished goals will collect here.'} action={filter === 'active' ? <Button onClick={() => setModal(true)}>Add a goal</Button> : undefined} /></div>}</div>{modal && <GoalModal onClose={() => setModal(false)} onSave={(value) => { add(value); setModal(false); }} />}</div>;
}
function GoalModal({ onClose, onSave }: { onClose: () => void; onSave: (value: Omit<Goal, 'id' | 'status' | 'progress'>) => void }) { const [value, setValue] = useState({ title: '', description: '', category: 'Personal', term: 'short' as Goal['term'], deadline: today }); const set = (key: keyof typeof value, next: string) => setValue((old) => ({ ...old, [key]: next })); return <Modal title="New goal" onClose={onClose}><form className="grid gap-4" onSubmit={(e) => { e.preventDefault(); if (value.title.trim()) onSave(value); }}><Field label="Goal"><input autoFocus required className={inputClass} value={value.title} onChange={(e) => set('title', e.target.value)} data-testid="input-goal-title" placeholder="What would feel meaningful to finish?" /></Field><Field label="Description"><textarea className={cx(inputClass, 'min-h-20')} value={value.description} onChange={(e) => set('description', e.target.value)} data-testid="input-goal-description" /></Field><div className="grid gap-3 sm:grid-cols-3"><Field label="Horizon"><select className={inputClass} value={value.term} onChange={(e) => set('term', e.target.value)} data-testid="select-goal-term"><option value="short">Short-term</option><option value="long">Long-term</option></select></Field><Field label="Category"><select className={inputClass} value={value.category} onChange={(e) => set('category', e.target.value)} data-testid="select-goal-category"><option>Personal</option><option>Work</option><option>Learning</option><option>Health</option></select></Field><Field label="Deadline"><input type="date" className={inputClass} value={value.deadline} onChange={(e) => set('deadline', e.target.value)} data-testid="input-goal-deadline" /></Field></div><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit">Create goal</Button></div></form></Modal>; }

function NotesPage({ store, update }: PageProps) {
  const [query, setQuery] = useState(''); const [modal, setModal] = useState<'new' | Note | null>(null);
  const notes = store.notes.filter((note) => `${note.title} ${note.content}`.toLowerCase().includes(query.toLowerCase()));
  const save = (value: Omit<Note, 'id' | 'updatedAt'>, editing?: Note) => update({ notes: editing ? store.notes.map((note) => note.id === editing.id ? { ...note, ...value, updatedAt: today } : note) : [{ ...value, id: newId('note'), updatedAt: today }, ...store.notes] });
  return <div className="space-y-7"><PageIntro eyebrow="Working memory" title="Notes" detail="Catch the thought before it turns into background noise." action={<Button onClick={() => setModal('new')} data-testid="button-add-note"><Plus className="h-4 w-4" />New note</Button>} /><div className="relative max-w-md"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input aria-label="search notes" data-testid="input-search-notes" className={cx(inputClass, 'pl-9')} value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search your notes" /></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{notes.length ? notes.map((note) => <Card key={note.id} className="pressable group flex min-h-[190px] flex-col p-5" style={{ borderTopColor: note.color, borderTopWidth: 3 }}><div className="mb-4 flex items-start justify-between"><div className="grid h-8 w-8 place-items-center rounded-lg" style={{ backgroundColor: `${note.color}18`, color: note.color }}><StickyNote className="h-4 w-4" /></div><div className="flex opacity-100 sm:opacity-0 sm:transition-opacity sm:group-hover:opacity-100"><IconButton label={`edit note ${note.title}`} onClick={() => setModal(note)}><Pencil className="h-3.5 w-3.5" /></IconButton><IconButton label={`delete note ${note.title}`} onClick={() => update({ notes: store.notes.filter((item) => item.id !== note.id) })}><Trash2 className="h-3.5 w-3.5" /></IconButton></div></div><h2 className="font-semibold">{note.title}</h2><p className="mt-2 line-clamp-4 text-sm leading-relaxed text-muted-foreground">{note.content}</p><p className="mt-auto pt-5 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Updated {shortDate(note.updatedAt)}</p></Card>) : <div className="sm:col-span-2 xl:col-span-3"><EmptyState title="No notes found" detail={query ? 'Try a different phrase.' : 'Your best ideas have not arrived yet.'} action={!query ? <Button onClick={() => setModal('new')}>Write a note</Button> : undefined} /></div>}</div>{modal && <NoteModal note={modal === 'new' ? undefined : modal} onClose={() => setModal(null)} onSave={(value) => { save(value, modal === 'new' ? undefined : modal); setModal(null); }} />}</div>;
}
function NoteModal({ note, onClose, onSave }: { note?: Note; onClose: () => void; onSave: (value: Omit<Note, 'id' | 'updatedAt'>) => void }) { const [value, setValue] = useState({ title: note?.title || '', content: note?.content || '', color: note?.color || colors[2] }); const set = (key: keyof typeof value, next: string) => setValue((old) => ({ ...old, [key]: next })); return <Modal title={note ? 'Edit note' : 'New note'} onClose={onClose}><form className="grid gap-4" onSubmit={(e) => { e.preventDefault(); if (value.title.trim()) onSave(value); }}><Field label="Title"><input autoFocus required className={inputClass} value={value.title} onChange={(e) => set('title', e.target.value)} data-testid="input-note-title" placeholder="A thought worth keeping" /></Field><Field label="Note"><textarea required className={cx(inputClass, 'min-h-40 resize-y')} value={value.content} onChange={(e) => set('content', e.target.value)} data-testid="input-note-content" placeholder="Write it in your own words." /></Field><Field label="Color"><div className="flex gap-2">{colors.map((item) => <button type="button" aria-label={`choose ${item} color`} key={item} onClick={() => set('color', item)} className={cx('h-8 w-8 rounded-full border-2', value.color === item ? 'border-foreground' : 'border-transparent')} style={{ backgroundColor: item }} />)}</div></Field><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit"><Save className="h-4 w-4" />Save note</Button></div></form></Modal>; }

function SettingsPage({ store, update, reset }: PageProps & { reset: () => void }) {
  const [profile, setProfile] = useState<Profile>(store.profile); const [confirm, setConfirm] = useState(false);
  useEffect(() => setProfile(store.profile), [store.profile]);
  const saveProfile = () => update({ profile }); const toggleTheme = () => { const theme = profile.theme === 'dark' ? 'light' : 'dark'; setProfile({ ...profile, theme }); update({ profile: { ...profile, theme } }); };
  return <div className="space-y-7"><PageIntro eyebrow="Control room" title="Settings" detail="Tune the space until it feels like yours." /><div className="grid gap-5 lg:grid-cols-[1fr_.7fr]"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Identity" title="Your profile" /><div className="grid gap-4"><Field label="Name"><input className={inputClass} value={profile.name} onChange={(e) => setProfile({ ...profile, name: e.target.value })} data-testid="input-profile-name" /></Field><Field label="Daily focus"><textarea className={cx(inputClass, 'min-h-24')} value={profile.focus} onChange={(e) => setProfile({ ...profile, focus: e.target.value })} data-testid="input-profile-focus" /></Field><div><Button onClick={saveProfile} data-testid="button-save-profile"><Save className="h-4 w-4" />Save profile</Button></div></div></Card><div className="grid gap-5"><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Atmosphere" title="Theme" /><button onClick={toggleTheme} data-testid="button-toggle-theme" className="flex w-full items-center justify-between rounded-xl border border-border bg-secondary/35 p-3 text-left"><span className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-lg bg-primary/12 text-primary">{profile.theme === 'dark' ? <Moon className="h-4 w-4" /> : <Sun className="h-4 w-4" />}</span><span><span className="block text-sm font-semibold">{profile.theme === 'dark' ? 'Night flight' : 'Daylight'}</span><span className="text-xs text-muted-foreground">Switch the visual temperature</span></span><span className="font-mono text-[10px] uppercase text-primary">{profile.theme}</span></span></button></Card><Card className="p-5 sm:p-6"><SectionHeading eyebrow="Fresh start" title="Local data" /><p className="text-sm leading-relaxed text-muted-foreground">Everything lives in this browser. Resetting clears tasks, notes, goals, and your profile back to the starter space.</p><Button variant="danger" className="mt-5" onClick={() => setConfirm(true)} data-testid="button-reset-data"><RotateCcw className="h-4 w-4" />Reset local data</Button></Card></div></div>{confirm && <Modal title="Reset your command centre?" onClose={() => setConfirm(false)}><p className="text-sm leading-relaxed text-muted-foreground">This removes your local changes and restores the starter space. There is no undo.</p><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setConfirm(false)}>Keep my data</Button><Button variant="danger" onClick={() => { reset(); setConfirm(false); }}>Reset everything</Button></div></Modal>}</div>;
}

function NotFound() { return <div className="mx-auto max-w-lg py-20 text-center"><p className="font-mono text-xs uppercase tracking-[.2em] text-primary">404 / off course</p><h1 className="mt-4 text-3xl font-semibold">This page is not in your orbit.</h1><Link href="/" className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-primary">Return to overview <ArrowUpRight className="h-4 w-4" /></Link></div>; }

function App() {
  const [store, setStore] = useState<Store>(() => loadStore());
  const update = (patch: Partial<Store>) => setStore((current) => { const next = { ...current, ...patch }; saveStore(next); return next; });
  const reset = () => { const next = loadStore(); localStorage.removeItem('personal-command-centre-v1'); const fresh = { ...next, ...loadStore() }; setStore(fresh); saveStore(fresh); };
  useEffect(() => { document.documentElement.classList.toggle('light', store.profile.theme === 'light'); document.documentElement.classList.toggle('dark', store.profile.theme === 'dark'); }, [store.profile.theme]);
  return <Layout store={store}><ErrorBoundary><Switch><Route path="/" component={() => <Dashboard store={store} update={update} />} /><Route path="/tasks" component={() => <TasksPage store={store} update={update} />} /><Route path="/study" component={() => <StudyPage store={store} update={update} />} /><Route path="/habits" component={() => <HabitsPage store={store} update={update} />} /><Route path="/goals" component={() => <GoalsPage store={store} update={update} />} /><Route path="/notes" component={() => <NotesPage store={store} update={update} />} /><Route path="/settings" component={() => <SettingsPage store={store} update={update} reset={reset} />} /><Route component={NotFound} /></Switch></ErrorBoundary></Layout>;
}

export default App;